# CELL 4: ANION BVS WIRING   (Eir 2.0.13)
#
# Hands the anion-centred engine the same valences the cation sums used, so
# the two sides of every bond are computed under one set of assumptions.

# Default valences for the species treated as anions before anything is known
# about the structure. Derived from the CELL 1 tables rather than typed out:
# this was a fifth hand-written copy of the same nine species, after
# _ANION_SET, ANION_ELEMENTS, the set inside extract_anion_parameter, and
# PROVISIONAL_ANIONS itself.
DEFAULT_ANION_VALENCES = {el: v for el, v in
                          {**ALWAYS_ANION, **AMPHOTERIC_ANION}.items()
                          if el in PROVISIONAL_ANIONS}


def anion_bvs_for_structure(cif_path, sites, cation_gii=None):
    """
    Run the anion-centred BVS for one structure, using the same valences that
    were reported for its cation sites so the two sums are directly
    comparable.

    The map is keyed by SITE LABEL and by element. Keying it by element alone
    silently gave every site of an element whichever valence appeared last in
    the site list: in Co3O4 the 8a Co(2+) and the 16d Co(3+) were then summed
    with a single R0. That affects 147 of 1881 spinels, 10 of 472 pyrochlores
    and 2 of 938 perovskites - the mixed-valence entries, which are exactly
    the ones an anion-side check is most useful for.
    """
    valences = {}
    _conflict = {}
    for s in sites:
        el, lab, v = s.get('element'), s.get('site_label'), s.get('valence')
        if v is None:
            continue
        if lab:
            valences[lab] = v
        if el:
            if el in valences and valences[el] != v:
                _conflict.setdefault(el, set()).add(valences[el])
                _conflict[el].add(v)
            valences.setdefault(el, v)
    if _conflict:
        # Reported, because the element-level fallback is now ambiguous for
        # these and only the site labels disambiguate them.
        for _el, _vs in _conflict.items():
            print(f'    [{_el} appears at {sorted(_vs)}; anion sums use the '
                  f'per-site valence where the label matches]')
    for el, dv in DEFAULT_ANION_VALENCES.items():
        valences.setdefault(el, dv)
    # v2.0.44: the shells the void guard cut, so both ends agree.
    _limits = {s.get('site_label'): s.get('shell_void_limit') for s in sites
               if s.get('site_label') and s.get('shell_void_limit') is not None}

    try:
        res = calculate_anion_bvs(cif_path, valences,
                                  shell_limits=_limits or None)
    except (NameError, AttributeError, TypeError, IndexError, KeyError):
        # A defect in the engine, not a property of the CIF. Swallowed, it
        # returns an empty anion result that reads as 'this structure has no
        # anion sites'.
        raise
    except Exception as e:
        print(f'    (anion BVS failed: {type(e).__name__}: {e})')
        res = []

    return res, summarise_anion_bvs(res, cation_gii=cation_gii)


print("anion_bvs_for_structure() ready")
